// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "zero", "Z"); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(c.owner()));
        vm.assume(burnAmount <= type(uint256).max / 2);
        address originalOwner = c.owner();
        vm.prank(nonOwner);
        try c.owned() {} catch {}
        vm.prank(nonOwner);
        try c.burn(burnAmount) {} catch {}
        assertEq(c.owner(), originalOwner);
    }
}
